import * as pdfjs from './vendor/pdf.min.mjs';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.mjs',import.meta.url).href;
const $=id=>document.getElementById(id),PDF=window.PDFLib;let pages=[],sources=[],current=0,output=null,view='original',busy=false,previewToken=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n>=1e6?(n/1e6).toFixed(2)+' MB':(n/1000).toFixed(1)+' KB';
const pdfOptions=bytes=>({data:bytes,cMapUrl:new URL('./vendor/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/standard_fonts/',import.meta.url).href,wasmUrl:new URL('./vendor/wasm/',import.meta.url).href,stopAtErrors:true});
function say(s){$('status').textContent=s}
function lock(on){busy=on;document.querySelectorAll('input,button').forEach(e=>e.disabled=on);if(!on){$('generate').disabled=!pages.length;$('resultTab').disabled=!output;updateNavigation()}}
function invalidate(){if(output?.url)URL.revokeObjectURL(output.url);if(output?.doc)output.doc.destroy();output=null;view='original';$('result').classList.add('hidden');$('resultTab').disabled=true;$('originalTab').classList.add('active');$('resultTab').classList.remove('active')}
function updateNavigation(){let count=view==='result'&&output?output.doc.numPages:pages.length;current=Math.max(0,Math.min(current,count-1));$('pagepos').textContent=count?`Page ${current+1} of ${count}`:'No pages yet';$('prev').disabled=busy||current===0;$('next').disabled=busy||current>=count-1;$('rotate').disabled=busy||!pages.length||view==='result';$('remove').disabled=busy||!pages.length||view==='result'}
function update(){sources=sources.filter(s=>pages.some(p=>p.source===s));$('filelist').innerHTML=sources.map((s,i)=>`<div class="file-row"><strong>${esc(s.name)}</strong><span>${pages.filter(p=>p.source===s).length} pages · ${fmt(s.size)}</span><button aria-label="Remove ${esc(s.name)}" data-remove="${i}">×</button></div>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(busy)return;let s=sources[+b.dataset.remove];pages=pages.filter(p=>p.source!==s);invalidate();update();say('File removed. Generate again to update the result.')});$('pagecount').textContent=pages.length+' pages';$('empty-note').classList.toggle('hidden',!!pages.length);$('generate').disabled=busy||!pages.length;updateNavigation();showPreview()}
async function drawPage(page,maxSide){let canvas=document.createElement('canvas');if(page.type==='pdf'){let p=await page.source.doc.getPage(page.number),raw=p.getViewport({scale:1,rotation:(p.rotate+page.rotation)%360}),v=p.getViewport({scale:Math.min(3,maxSide/Math.max(raw.width,raw.height)),rotation:(p.rotate+page.rotation)%360});canvas.width=Math.max(1,Math.round(v.width));canvas.height=Math.max(1,Math.round(v.height));await p.render({canvasContext:canvas.getContext('2d'),viewport:v,background:'rgb(255,255,255)'}).promise;return {canvas,width:raw.width,height:raw.height}}let img=page.source.image,rot=page.rotation%180!==0,iw=rot?img.height:img.width,ih=rot?img.width:img.height,scale=Math.min(1,maxSide/Math.max(iw,ih));canvas.width=Math.max(1,Math.round(iw*scale));canvas.height=Math.max(1,Math.round(ih*scale));let ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(page.rotation*Math.PI/180);ctx.drawImage(img,-img.width*scale/2,-img.height*scale/2,img.width*scale,img.height*scale);let width=iw/Math.max(iw,ih)*842,height=ih/Math.max(iw,ih)*842;return {canvas,width,height}}
async function showPreview(){let token=++previewToken;if(!pages.length){$('preview').innerHTML='<div class="placeholder"><div class="ghost-page"><span>↘</span><i></i><i></i><i></i></div><h4>Your document goes here.</h4><p>See every page before you send it.</p></div>';return}try{let page;if(view==='result'&&output)page={type:'pdf',source:{doc:output.doc},number:current+1,rotation:0};else page=pages[current];let {canvas}=await drawPage(page,1100);if(token===previewToken)$('preview').replaceChildren(canvas)}catch(e){if(token===previewToken)$('preview').textContent='This page could not be previewed. '+e.message}}
async function addFiles(list){if(busy||!list.length)return;invalidate();lock(true);say('Reading files locally…');let incoming=[],newPages=[];try{if(sources.reduce((n,s)=>n+s.size,0)+Array.from(list).reduce((n,f)=>n+f.size,0)>25e6)throw Error('Use at most 25 MB of source files in one session.');for(let f of list){let bytes=new Uint8Array(await f.arrayBuffer()),signature=new TextDecoder().decode(bytes.slice(0,5)),s={name:f.name,size:f.size};if(signature==='%PDF-'){s.doc=await pdfjs.getDocument(pdfOptions(bytes)).promise;incoming.push(s);if(pages.length+newPages.length+s.doc.numPages>30)throw Error('Use at most 30 pages. Split this document first.');for(let n=1;n<=s.doc.numPages;n++)newPages.push({type:'pdf',source:s,number:n,rotation:0})}else{if(!/^image\/(jpeg|png|webp)$/.test(f.type))throw Error('Supported files are PDF, JPG, PNG and WebP.');s.image=await createImageBitmap(f);incoming.push(s);if(s.image.width*s.image.height>40e6)throw Error('An image exceeds the 40-megapixel limit. Resize it first.');newPages.push({type:'image',source:s,rotation:0});if(pages.length+newPages.length>30)throw Error('Use at most 30 pages.')}}sources.push(...incoming);pages.push(...newPages);say(`${newPages.length} pages added. Check the preview, then make it fit.`)}catch(e){incoming.forEach(s=>{s.doc?.destroy();s.image?.close()});say('Could not add these files: '+(e.name==='PasswordException'?'Password-protected PDFs are not supported. Export an unlocked copy first.':e.message))}finally{lock(false);update();$('files').value=''}}
async function jpeg(canvas,q){let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',q));if(!blob)throw Error('Your browser could not encode a page.');return new Uint8Array(await blob.arrayBuffer())}
async function build(maxSide,q,trial){let doc=await PDF.PDFDocument.create();doc.setProducer('UnderLimit — browser-local PDF preparation');doc.setCreator('UnderLimit');for(let i=0;i<pages.length;i++){say(`Attempt ${trial} · preparing page ${i+1} of ${pages.length}…`);let {canvas,width,height}=await drawPage(pages[i],maxSide),img=await doc.embedJpg(await jpeg(canvas,q));doc.addPage([width,height]).drawImage(img,{x:0,y:0,width,height});canvas.width=1;canvas.height=1}return doc.save({useObjectStreams:true})}
async function generate(){if(busy||!pages.length)return;let mb=+$('limit').value,max=+$('maxpages').value;if(!Number.isFinite(mb)||mb<.05||mb>100){say('Choose a size limit between 0.05 and 100 MB.');return}if($('maxpages').value&&(!Number.isInteger(max)||max<1||max>30)){say('Maximum pages must be a whole number from 1 to 30.');return}invalidate();if(max&&pages.length>max){say(`You have ${pages.length} pages, but the limit is ${max}. Remove pages using the preview before generating. Nothing will be removed automatically.`);return}lock(true);try{let compact=document.querySelector('[name=mode]:checked').value==='compact',attempts=compact?[[1500,.7],[1200,.6],[1000,.5],[800,.4],[600,.3]]:[[2200,.88],[1800,.78],[1400,.65],[1100,.52],[850,.4],[650,.3]];let best=null,used=null;for(let i=0;i<attempts.length;i++){let [side,q]=attempts[i],bytes=await build(side,q,i+1);if(!best||bytes.length<best.length){best=bytes;used={side,q}}if(best.length<mb*1e6)break;await new Promise(resolve=>setTimeout(resolve,0))}let doc=await pdfjs.getDocument(pdfOptions(best.slice())).promise;let fits=best.length<mb*1e6,sourceSize=sources.reduce((s,f)=>s+f.size,0),url=URL.createObjectURL(new Blob([best],{type:'application/pdf'}));output={url,doc,size:best.length};let result=$('result');result.className='card result'+(fits?'':' fail');result.innerHTML=`<span class="eyebrow">${fits?'CHECKED AGAINST YOUR RULES':'LIMIT NOT REACHED'}</span><h3>${fits?'Fits just right.':'Still a little too big.'}</h3><div class="checks"><span>${fits?'✓':'×'} Size ${fits?'passed':'not met'}</span><span>✓ ${doc.numPages} pages${max?' / '+max+' max':''}</span><span>✓ PDF format</span></div><dl><dt>Original files</dt><dd>${fmt(sourceSize)}</dd><dt>Prepared PDF</dt><dd>${fmt(best.length)} (${best.length.toLocaleString()} bytes)</dd><dt>Your size limit</dt><dd>${fmt(mb*1e6)}</dd><dt>Maximum rendered edge</dt><dd>${used.side} px</dd></dl><p>${fits?'The file passes the size check. Inspect small text and important details before submitting.':'The smallest attempted result still exceeds your limit. Try fewer pages, or increase the allowed size. This download does not meet your requested limit.'} Text and interactive PDF features have been flattened.</p><a class="button dark full" href="${url}" download="underlimit-prepared.pdf">${fits?'Download prepared PDF':'Download best attempt'} <span>↓</span></a>`;$('resultTab').disabled=false;view='result';$('resultTab').classList.add('active');$('originalTab').classList.remove('active');current=0;say(fits?'Ready. Size, page count and format checked. Please inspect readability.':'Your size limit could not be reached with the available settings.');showPreview()}catch(e){say('Could not prepare this document: '+e.message)}finally{lock(false)}}
$('files').onchange=e=>addFiles(e.target.files);$('drop').ondragover=e=>{e.preventDefault();if(!busy)$('drop').classList.add('drag')};$('drop').ondragleave=()=>$('drop').classList.remove('drag');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('drag');addFiles(e.dataTransfer.files)};
$('generate').onclick=generate;document.querySelectorAll('[data-limit]').forEach(b=>b.onclick=()=>{$('limit').value=b.dataset.limit;settingsChanged()});function settingsChanged(){if(busy)return;invalidate();document.querySelectorAll('[data-limit]').forEach(b=>b.classList.toggle('selected',b.dataset.limit===$('limit').value));say(pages.length?'Requirements changed. Generate again to check the new limits.':'Add a file to get started.');update()}
['limit','maxpages'].forEach(id=>$(id).oninput=settingsChanged);document.querySelectorAll('[name=mode]').forEach(e=>e.onchange=settingsChanged);$('prev').onclick=()=>{current--;updateNavigation();showPreview()};$('next').onclick=()=>{current++;updateNavigation();showPreview()};$('rotate').onclick=()=>{pages[current].rotation=(pages[current].rotation+90)%360;invalidate();update()};$('remove').onclick=()=>{pages.splice(current,1);invalidate();update();say('Page removed. Generate again to update the result.')};$('originalTab').onclick=()=>{view='original';$('originalTab').classList.add('active');$('resultTab').classList.remove('active');updateNavigation();showPreview()};$('resultTab').onclick=()=>{if(!output)return;view='result';$('resultTab').classList.add('active');$('originalTab').classList.remove('active');updateNavigation();showPreview()};
$('sample').onclick=async()=>{if(busy)return;lock(true);say('Creating a sample document on your device…');try{let doc=await PDF.PDFDocument.create();for(let p=0;p<3;p++){let c=document.createElement('canvas');c.width=1400;c.height=1900;let ctx=c.getContext('2d');ctx.fillStyle='#fffdf6';ctx.fillRect(0,0,1400,1900);ctx.fillStyle='#263a30';ctx.font='bold 64px Georgia';ctx.fillText('A little less paperwork.',110,170);ctx.font='24px sans-serif';ctx.fillText('UNDERLIMIT / SAMPLE DOCUMENT / PAGE '+(p+1),110,230);let seed=42+p;for(let y=330;y<1050;y+=8)for(let x=110;x<1290;x+=8){seed=(seed*1664525+1013904223)>>>0;ctx.fillStyle=`hsl(${20+seed%140} 30% ${45+seed%45}%)`;ctx.fillRect(x,y,8,8)}ctx.fillStyle='#35453c';ctx.font='24px sans-serif';for(let i=0;i<12;i++)ctx.fillText('Keep the important details. Make room for what comes next.',110,1180+i*40);let img=await doc.embedJpg(await jpeg(c,.96));doc.addPage([595,808]).drawImage(img,{x:0,y:0,width:595,height:808})}let bytes=await doc.save();lock(false);$('limit').value=.4;settingsChanged();await addFiles([new File([bytes],'sample-document.pdf',{type:'application/pdf'})])}catch(e){say(e.message);lock(false)}};
